INSERT INTO translations (key, value, locale) VALUES
  ('verificationCaptureStatusUseCorrectHand', 'Wrong hand — use your {hand} hand', 'en'),
  ('verificationCaptureRetry', 'Retry', 'en'),
  ('verificationGestureClosedFistTitle', 'Show a closed fist with your right hand', 'en'),
  ('verificationGestureClosedFistDescription', 'Curl the four fingers of your right hand down into your palm and wrap your thumb across the front of them. Keep your wrist straight, your knuckles facing the camera, and hold the fist beside your face.', 'en'),
  ('verificationGestureOpenPalmTitle', 'Show an open palm with your right hand', 'en'),
  ('verificationGestureOpenPalmDescription', 'Hold your right hand up with your palm facing the camera and all five fingers spread apart, pointing upward. Keep every finger straight and fully visible, and hold your hand beside your face.', 'en'),
  ('verificationGesturePeaceSignTitle', 'Show a peace sign with your right hand', 'en'),
  ('verificationGesturePeaceSignDescription', 'Extend the index and middle fingers of your right hand upward in a V shape and press them apart. Curl your ring finger and pinky down into your palm, hold them with your thumb, and keep your palm facing the camera beside your face.', 'en'),
  ('verificationGesturePointingUpTitle', 'Point up with your right index finger', 'en'),
  ('verificationGesturePointingUpDescription', 'Extend only the index finger of your right hand straight upward and make a fist with the other three fingers, held down with your thumb. Keep your palm facing the camera and your hand beside your face.', 'en'),
  ('verificationGestureThumbsDownTitle', 'Show a thumbs-down with your right hand', 'en'),
  ('verificationGestureThumbsDownDescription', 'Make a fist with your right hand and point your thumb straight down toward the floor. Keep the other fingers curled, your knuckles facing the camera, and hold your hand beside your face.', 'en'),
  ('verificationGestureThumbsUpTitle', 'Show a thumbs-up with your right hand', 'en'),
  ('verificationGestureThumbsUpDescription', 'Make a fist with your right hand and point your thumb straight up toward the ceiling. Keep the other fingers curled, your palm facing sideways, and hold your hand beside your face.', 'en'),
  ('verificationGestureClosedFistLeftDescription', 'Curl the four fingers of your left hand down into your palm and wrap your thumb across the front of them. Keep your wrist straight, your knuckles facing the camera, and hold the fist beside your face.', 'en'),
  ('verificationGestureOpenPalmLeftDescription', 'Hold your left hand up with your palm facing the camera and all five fingers spread apart, pointing upward. Keep every finger straight and fully visible, and hold your hand beside your face.', 'en'),
  ('verificationGesturePeaceSignLeftDescription', 'Extend the index and middle fingers of your left hand upward in a V shape and press them apart. Curl your ring finger and pinky down into your palm, hold them with your thumb, and keep your palm facing the camera beside your face.', 'en'),
  ('verificationGesturePointingUpLeftDescription', 'Extend only the index finger of your left hand straight upward and make a fist with the other three fingers, held down with your thumb. Keep your palm facing the camera and your hand beside your face.', 'en'),
  ('verificationGestureThumbsDownLeftDescription', 'Make a fist with your left hand and point your thumb straight down toward the floor. Keep the other fingers curled, your knuckles facing the camera, and hold your hand beside your face.', 'en'),
  ('verificationGestureThumbsUpLeftDescription', 'Make a fist with your left hand and point your thumb straight up toward the ceiling. Keep the other fingers curled, your palm facing sideways, and hold your hand beside your face.', 'en'),
  ('verificationComparisonMismatchHeader', 'What didn''t match', 'en'),
  ('verificationComparisonNoBoxes', 'The AI found differences between your photos but could not mark their exact locations.', 'en'),
  ('verificationComparisonProfilePhotoLabel', 'Profile photo', 'en'),
  ('verificationComparisonTitle', 'Photo comparison', 'en'),
  ('verificationComparisonVerificationPhotoLabel', 'Verification photo', 'en'),
  ('verificationPromptBodyRejected', 'Your photo verification was not approved. Try again with a clearer photo and the requested hand gesture.', 'en'),
  ('verificationPromptBodyUnverified', 'Verifying your photo keeps MatchMe real and safe. Take a quick selfie with a hand gesture — it only takes a minute.', 'en'),
  ('verificationPromptLater', 'Later', 'en'),
  ('verificationPromptTitle', 'Photo verification', 'en')
INSERT INTO translations (key, value, locale) VALUES
  ('verificationCaptureStatusUseCorrectHand', 'Mano equivocada — usa tu mano {hand}', 'es'),
  ('verificationCaptureHandLeft', 'izquierda', 'es'),
  ('verificationCaptureHandRight', 'derecha', 'es'),
  ('verificationCaptureRetry', 'Reintentar', 'es'),
  ('verificationGestureClosedFistTitle', 'Muestra un puño cerrado con tu mano derecha', 'es'),
  ('verificationGestureClosedFistDescription', 'Dobla los cuatro dedos de tu mano derecha hacia tu palma y cruza el pulgar por delante. Mantén la muñeca recta, los nudillos hacia la cámara y el puño junto a tu rostro.', 'es'),
  ('verificationGestureOpenPalmTitle', 'Muestra una palma abierta con tu mano derecha', 'es'),
  ('verificationGestureOpenPalmDescription', 'Sostén tu mano derecha con la palma hacia la cámara y los cinco dedos separados y hacia arriba. Mantén todos los dedos rectos y completamente visibles, y sostén tu mano junto a tu rostro.', 'es'),
  ('verificationGesturePeaceSignTitle', 'Muestra una señal de paz con tu mano derecha', 'es'),
  ('verificationGesturePeaceSignDescription', 'Extiende los dedos índice y medio de tu mano derecha hacia arriba en forma de V y sepáralos. Dobla el anular y el meñique hacia tu palma, mantenlos sujetos con el pulgar, y mantén la palma hacia la cámara junto a tu rostro.', 'es'),
  ('verificationGesturePointingUpTitle', 'Apunta hacia arriba con tu dedo índice derecho', 'es'),
  ('verificationGesturePointingUpDescription', 'Extiende solo el dedo índice de tu mano derecha recto hacia arriba y haz un puño con los otros tres dedos, sujetos con tu pulgar. Mantén la palma hacia la cámara y tu mano junto a tu rostro.', 'es'),
  ('verificationGestureThumbsDownTitle', 'Muestra un pulgar hacia abajo con tu mano derecha', 'es'),
  ('verificationGestureThumbsDownDescription', 'Haz un puño con tu mano derecha y apunta el pulgar recto hacia el suelo. Mantén los otros dedos doblados, los nudillos hacia la cámara y tu mano junto a tu rostro.', 'es'),
  ('verificationGestureThumbsUpTitle', 'Muestra un pulgar hacia arriba con tu mano derecha', 'es'),
  ('verificationGestureThumbsUpDescription', 'Haz un puño con tu mano derecha y apunta el pulgar recto hacia el techo. Mantén los otros dedos doblados, la palma hacia un lado y tu mano junto a tu rostro.', 'es'),
  ('verificationGestureClosedFistLeftDescription', 'Dobla los cuatro dedos de tu mano izquierda hacia tu palma y cruza el pulgar por delante. Mantén la muñeca recta, los nudillos hacia la cámara y el puño junto a tu rostro.', 'es'),
  ('verificationGestureOpenPalmLeftDescription', 'Sostén tu mano izquierda con la palma hacia la cámara y los cinco dedos separados y hacia arriba. Mantén todos los dedos rectos y completamente visibles, y sostén tu mano junto a tu rostro.', 'es'),
  ('verificationGesturePeaceSignLeftDescription', 'Extiende los dedos índice y medio de tu mano izquierda hacia arriba en forma de V y sepáralos. Dobla el anular y el meñique hacia tu palma, mantenlos sujetos con el pulgar, y mantén la palma hacia la cámara junto a tu rostro.', 'es'),
  ('verificationGesturePointingUpLeftDescription', 'Extiende solo el dedo índice de tu mano izquierda recto hacia arriba y haz un puño con los otros tres dedos, sujetos con tu pulgar. Mantén la palma hacia la cámara y tu mano junto a tu rostro.', 'es'),
  ('verificationGestureThumbsDownLeftDescription', 'Haz un puño con tu mano izquierda y apunta el pulgar recto hacia el suelo. Mantén los otros dedos doblados, los nudillos hacia la cámara y tu mano junto a tu rostro.', 'es'),
  ('verificationGestureThumbsUpLeftDescription', 'Haz un puño con tu mano izquierda y apunta el pulgar recto hacia el techo. Mantén los otros dedos doblados, la palma hacia un lado y tu mano junto a tu rostro.', 'es'),
  ('verificationComparisonMismatchHeader', 'Lo que no coincide', 'es'),
  ('verificationComparisonNoBoxes', 'La IA detectó diferencias entre tus fotos, pero no pudo marcar sus ubicaciones exactas.', 'es'),
  ('verificationComparisonProfilePhotoLabel', 'Foto de perfil', 'es'),
  ('verificationComparisonTitle', 'Comparación de fotos', 'es'),
  ('verificationComparisonVerificationPhotoLabel', 'Foto de verificación', 'es'),
  ('verificationPromptBodyRejected', 'Tu verificación de foto no fue aprobada. Inténtalo de nuevo con una foto más clara y el gesto de mano solicitado.', 'es'),
  ('verificationPromptBodyUnverified', 'Verificar tu foto mantiene MatchMe real y seguro. Tómate un selfie rápido con un gesto de mano — solo toma un minuto.', 'es'),
  ('verificationPromptLater', 'Más tarde', 'es'),
  ('verificationPromptTitle', 'Verificación de foto', 'es')
INSERT INTO translations (key, value, locale) VALUES
  ('verificationCaptureStatusUseCorrectHand', 'יד שגוייה — השתמש/י ביד ה{hand}', 'he'),
  ('verificationCaptureRetry', 'נסה שוב', 'he'),
  ('verificationCaptureHandLeft', 'השמאלית', 'he'),
  ('verificationCaptureHandRight', 'הימנית', 'he'),
  ('verificationGestureClosedFistTitle', 'הראה/י אגרוף קמוץ ביד ימין', 'he'),
  ('verificationGestureClosedFistDescription', 'כווץ את ארבע אצבעות יד ימין לתוך כף היד ועטוף את האגודל מעליהן. השאר/י את שורש כף היד ישר, את המפרקים פונים למצלמה, והחזק/י את האגרוף ליד הפנים.', 'he'),
  ('verificationGestureOpenPalmTitle', 'הראה/י כף יד פתוחה ביד ימין', 'he'),
  ('verificationGestureOpenPalmDescription', 'הרם/י את יד ימין עם כף היד פונה למצלמה וחמש האצבעות פשוקות ומופנות למעלה. השאר/י כל אצבע ישרה וגלוייה לחלוטין, והחזק/י את היד ליד הפנים.', 'he'),
  ('verificationGesturePeaceSignTitle', 'הראה/י סימן שלום ביד ימין', 'he'),
  ('verificationGesturePeaceSignDescription', 'הצא/י את האצבע המורה ואת האמה של יד ימין למעלה בצורת V והפרד/י ביניהן. כופף/י את הקמיצה ואת הזרת לתוך כף היד, החזק/י אותן עם האגודל, והשאר/י את כף היד פונה למצלמה ליד הפנים.', 'he'),
  ('verificationGesturePointingUpTitle', 'הצביע/י למעלה עם האצבע המורה של יד ימין', 'he'),
  ('verificationGesturePointingUpDescription', 'הצא/י רק את האצבע המורה של יד ימין ישר למעלה ועשה/י אגרוף עם שלוש האצבעות הנותרות, מוחזקות עם האגודל. השאר/י את כף היד פונה למצלמה והיד ליד הפנים.', 'he'),
  ('verificationGestureThumbsDownTitle', 'הראה/י אגודל למטה ביד ימין', 'he'),
  ('verificationGestureThumbsDownDescription', 'עשה/י אגרוף ביד ימין והפנה/י את האגודל ישר לרצפה. השאר/י את שאר האצבעות כפופות, את המפרקים פונים למצלמה, והחזק/י את היד ליד הפנים.', 'he'),
  ('verificationGestureThumbsUpTitle', 'הראה/י אגודל למעלה ביד ימין', 'he'),
  ('verificationGestureThumbsUpDescription', 'עשה/י אגרוף ביד ימין והפנה/י את האגודל ישר לתקרה. השאר/י את שאר האצבעות כפופות, את כף היד פונה הצידה, והחזק/י את היד ליד הפנים.', 'he'),
  ('verificationGestureClosedFistLeftDescription', 'כווץ את ארבע אצבעות יד שמאל לתוך כף היד ועטוף את האגודל מעליהן. השאר/י את שורש כף היד ישר, את המפרקים פונים למצלמה, והחזק/י את האגרוף ליד הפנים.', 'he'),
  ('verificationGestureOpenPalmLeftDescription', 'הרם/י את יד שמאל עם כף היד פונה למצלמה וחמש האצבעות פשוקות ומופנות למעלה. השאר/י כל אצבע ישרה וגלוייה לחלוטין, והחזק/י את היד ליד הפנים.', 'he'),
  ('verificationGesturePeaceSignLeftDescription', 'הצא/י את האצבע המורה ואת האמה של יד שמאל למעלה בצורת V והפרד/י ביניהן. כופף/י את הקמיצה ואת הזרת לתוך כף היד, החזק/י אותן עם האגודל, והשאר/י את כף היד פונה למצלמה ליד הפנים.', 'he'),
  ('verificationGesturePointingUpLeftDescription', 'הצא/י רק את האצבע המורה של יד שמאל ישר למעלה ועשה/י אגרוף עם שלוש האצבעות הנותרות, מוחזקות עם האגודל. השאר/י את כף היד פונה למצלמה והיד ליד הפנים.', 'he'),
  ('verificationGestureThumbsDownLeftDescription', 'עשה/י אגרוף ביד שמאל והפנה/י את האגודל ישר לרצפה. השאר/י את שאר האצבעות כפופות, את המפרקים פונים למצלמה, והחזק/י את היד ליד הפנים.', 'he'),
  ('verificationGestureThumbsUpLeftDescription', 'עשה/י אגרוף ביד שמאל והפנה/י את האגודל ישר לתקרה. השאר/י את שאר האצבעות כפופות, את כף היד פונה הצידה, והחזק/י את היד ליד הפנים.', 'he'),
  ('verificationComparisonMismatchHeader', 'מה לא תואם', 'he'),
  ('verificationComparisonNoBoxes', 'ה-AI זיהה הבדלים בין התמונות שלך אך לא הצליח לסמן את המיקומים המדויקים שלהם.', 'he'),
  ('verificationComparisonProfilePhotoLabel', 'תמונת פרופיל', 'he'),
  ('verificationComparisonTitle', 'השוואת תמונות', 'he'),
  ('verificationComparisonVerificationPhotoLabel', 'תמונת אימות', 'he'),
  ('verificationPromptBodyRejected', 'אימות התמונה שלך לא אושר. נסה/י שוב עם תמונה ברורה יותר ועם תנועת היד המבוקשת.', 'he'),
  ('verificationPromptBodyUnverified', 'אימות התמונה שומר על MatchMe אמיתי ובטוח. צלם/י סלפי מהיר עם תנועת יד — זה לוקח רק דקה.', 'he'),
  ('verificationPromptLater', 'אחר כך', 'he'),
  ('verificationPromptTitle', 'אימות תמונה', 'he')
